import { delegate } from 'kerfjs';
import type { SafeHtml } from 'kerfjs';
import { TokenSearchField, readTokenSearchField, placeTokenSearchCaret } from '@kerfjs/ui/token-search-field';
import '@kerfjs/ui/layout.css';
import './search-editor.css';

interface Filter { id: string; label: string; expression: string }
interface SearchState { text: string; tokens: Filter[] }
interface SearchApplication {
  parse(text: string): { text: string; filters: Omit<Filter, 'id'>[] };
  suggestions(text: string): Omit<Filter, 'id'>[];
  search(state: SearchState): void;
}
export function mountSearchEditor(root: HTMLElement, paint: (content: SafeHtml) => void, app: SearchApplication, id = 'workspace-search') {
  let state: SearchState = { text: '', tokens: [] };
  let suggestions: Omit<Filter, 'id'>[] = [];
  let editingId: string | null = null;
  let nextId = 0;
  let message = '';
  const editor = () => root.querySelector<HTMLElement>('[role="searchbox"]')!;
  function read() {
    const value = readTokenSearchField(editor());
    state.text = typeof value === 'string' ? value : value.text;
  }
  const render = () => paint(<section class="search-editor kui-layout kui-section-stack">
    <TokenSearchField id={id} label="Search workspace tasks" text={state.text} tokens={state.tokens} editAction="search-edit-token" removeAction="search-remove-token" clearAction="search-clear" />
    <div class="kui-control-cluster"><button class="search-button" type="button" data-action="search-submit">Search</button></div>
    <p id={id + '-help'}>Type a search expression. Press Enter to apply filters, or Tab to edit, remove, clear, or choose a suggested filter.</p>
    <div aria-label="Suggested filters" class="kui-control-cluster">
      {suggestions.map((filter, index) => <button class="search-button" type="button" data-action="search-suggestion" data-index={index}>{editingId ? 'Replace with ' : 'Add '}{filter.label}</button>)}
      {editingId && <button class="search-button" type="button" data-action="search-cancel-edit">Cancel filter edit</button>}
    </div>
    <p role="status" aria-live="polite" aria-atomic="true">{message}</p>
  </section>);
  function updateSuggestions() {
    suggestions = app.suggestions(state.text);
    message = suggestions.length + ' suggested filters.' + (editingId ? ' Choose one to replace the selected filter.' : '');
    // TokenSearchField leaves browser-edited text alone while the tokens are unchanged.
    render();
  }
  function replaceDom() {
    render();
    const field = editor();
    field.focus();
    placeTokenSearchCaret(field);
  }
  function submit() {
    read();
    const parsed = app.parse(state.text);
    if (editingId && parsed.filters.length !== 1) {
      message = 'Enter one filter expression to replace this filter.'; render(); return;
    }
    const added = parsed.filters.map(filter => ({ ...filter, id: 'filter-' + ++nextId }));
    state = { text: parsed.text, tokens: editingId
      ? state.tokens.map(token => token.id === editingId ? { ...added[0]!, id: token.id } : token)
      : [...state.tokens, ...added] };
    editingId = null; suggestions = [];
    message = 'Search updated. ' + state.tokens.length + ' filters applied.';
    replaceDom(); app.search({ text: state.text, tokens: [...state.tokens] });
  }
  const offInput = delegate(root, 'input', '[role="searchbox"]', () => { read(); updateSuggestions(); });
  const offKeys = delegate(root, 'keydown', '[role="searchbox"]', (event) => {
    const key = event as KeyboardEvent;
    if (key.isComposing) return;
    // Nested token buttons retain their native Enter and Space activation.
    if (key.target !== editor()) return;
    if (key.key === 'Enter') { key.preventDefault(); submit(); }
    if (key.key === 'Escape' && editingId) { key.preventDefault(); editingId = null; message = 'Filter edit canceled.'; replaceDom(); }
  });
  const offActions = delegate(root, 'click', '[data-action]', (_event, element) => {
    const action = element.dataset.action;
    if (!action?.startsWith('search-')) return;
    read();
    const tokenId = element.dataset.tokenId ?? element.closest<HTMLElement>('[data-token-id]')?.dataset.tokenId;
    if (action === 'search-submit') return submit();
    if (action === 'search-clear') {
      editor().textContent = '';
      state = { text: '', tokens: [] }; editingId = null; suggestions = []; message = 'Search cleared.';
      replaceDom(); app.search({ text: '', tokens: [] }); return;
    }
    if (action === 'search-edit-token') {
      const token = state.tokens.find(item => item.id === tokenId);
      if (!token) return;
      editingId = token.id;
      suggestions = app.suggestions(token.expression);
      message = 'Editing ' + token.label + '. Choose a replacement below, or cancel.';
      render();
      root.querySelector<HTMLElement>('[data-action="search-suggestion"], [data-action="search-cancel-edit"]')?.focus();
      return;
    }
    if (action === 'search-remove-token') {
      const token = state.tokens.find(item => item.id === tokenId);
      if (!token) return;
      state.tokens = state.tokens.filter(item => item.id !== token.id);
      if (editingId === token.id) editingId = null;
      message = token.label + ' removed.';
    } else if (action === 'search-suggestion') {
      const filter = suggestions[Number(element.dataset.index)];
      if (!filter) return;
      state.tokens = editingId ? state.tokens.map(token => token.id === editingId ? { ...filter, id: token.id } : token) : [...state.tokens, { ...filter, id: 'filter-' + ++nextId }];
      editingId = null; suggestions = []; message = 'Filter applied.';
    } else if (action === 'search-cancel-edit') {
      editingId = null; suggestions = []; message = 'Filter edit canceled.';
    } else return;
    replaceDom(); app.search({ text: state.text, tokens: [...state.tokens] });
  });
  render();
  return { announceResults(count: number) { message = count + ' matching tasks.'; render(); }, dispose() { offInput(); offKeys(); offActions(); } };
}

