.search-editor { min-width: 0; color: var(--kui-color-text); }
.search-editor p { margin: 0; overflow-wrap: anywhere; }
.search-button { min-height: 2.5rem; padding: var(--kui-space-xs) var(--kui-space-s); border: 1px solid var(--kui-color-border); border-radius: var(--kui-radius-m); font: inherit; background: var(--kui-color-surface); color: var(--kui-color-text); }
.search-button:focus-visible { outline: var(--kui-focus-ring); outline-offset: 2px; }
